import{_ as t,o as n,c as i,a2 as a}from"./chunks/framework.vLhlLNVn.js";const r="/assets/einheit-beheben.CnWHg7pI.png",p=JSON.parse('{"title":"Log-Meldungen und Fehler beim Einrichten","description":"","frontmatter":{"order":1,"adapter":"sourceanalytix","editLink":"https://github.com/DrozmotiX/ioBroker.sourceanalytix/edit/main/docs/de/04.fehlerbehebung/01.log-meldungen.md"},"headers":[],"relativePath":"de/adapter/sourceanalytix/fehlerbehebung/log-meldungen.md","filePath":"de/adapter/sourceanalytix/fehlerbehebung/log-meldungen.md","lastUpdated":null}'),l={name:"de/adapter/sourceanalytix/fehlerbehebung/log-meldungen.md"};function o(d,e,s,u,h,c){return n(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="log-meldungen-und-fehler-beim-einrichten" tabindex="-1">Log-Meldungen und Fehler beim Einrichten <a class="header-anchor" href="#log-meldungen-und-fehler-beim-einrichten" aria-label="Permalink to &quot;Log-Meldungen und Fehler beim Einrichten&quot;">​</a></h1><p><a id="error-unit-not-supported-no"></a></p><h2 id="fehler-unit-not-supported-no-unit-defined-–-wie-trage-ich-die-einheit-ein" tabindex="-1">Fehler &quot;unit not supported&quot; / &quot;No unit defined&quot; – wie trage ich die Einheit ein? <a class="header-anchor" href="#fehler-unit-not-supported-no-unit-defined-–-wie-trage-ich-die-einheit-ein" aria-label="Permalink to &quot;Fehler &quot;unit not supported&quot; / &quot;No unit defined&quot; – wie trage ich die Einheit ein?&quot;">​</a></h2><p>SourceAnalytix findet keine Einheit, mit der es rechnen kann, und lässt die Quelle aus. Klicke im Tab „Probleme“ bei „Einheit fehlt oder wird nicht erkannt“ auf „Beheben“ und wähle die Einheit, in der das Gerät liefert.</p><p>Im Log steht dazu <code>No unit defined for &lt;Datenpunkt&gt;, cannot execute calculations !</code>.</p><p>Ursachen: Das Objekt hat keine Einheit (oft bei Skript-Datenpunkten), die Einheit ist ausgeschrieben wie <code>Watt</code>, oder die Größe wird nicht unterstützt, etwa <code>%</code> oder <code>h</code>. Schreibweisen wie <code>m3</code> oder <code>kwh</code> erkennt SourceAnalytix selbst.</p><p><img src="'+r+'" alt="Tab „Probleme“ mit geöffnetem Dialog „Einheit beheben“"></p><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Wähle die Einheit, die das Gerät <strong>liefert</strong>, nicht die, die du sehen willst. Die Anzeige-Einheit kommt aus der Preisdefinition. <code>kWh</code> statt <code>Wh</code> macht alle Werte 1.000-mal zu groß.</p></div><p>Meldet der Tab „Probleme“ stattdessen „Einheit passt nicht zum Preis“, etwa <code>kg</code> und <code>kWh</code>, wähle eine Preisdefinition mit passender Einheit.</p><p><strong>Siehe auch:</strong> <a href="./../referenz/einstellungen#units-supported-energy-volume-weight">Welche Einheiten werden unterstützt?</a> · <a href="./../anleitungen/quellen-und-einheiten#unit-datapoint-kwh-wh-m3">Welche Einheit am Datenpunkt?</a></p><p><a id="error-known-valueatdevicereset-known-cumulative"></a></p><h2 id="fehler-known-valueatdevicereset-known-cumulative-value" tabindex="-1">Fehler &quot;Known valueAtDeviceReset &gt; known cumulative value&quot; <a class="header-anchor" href="#fehler-known-valueatdevicereset-known-cumulative-value" aria-label="Permalink to &quot;Fehler &quot;Known valueAtDeviceReset &gt; known cumulative value&quot;&quot;">​</a></h2><p>Der gespeicherte Offset ist größer als der Gesamtstand. Die Quelle läuft trotzdem weiter, und SourceAnalytix richtet den Offset mit dem nächsten Wert selbst aus. Prüfe danach den „Gesamtstand“ der Quelle.</p><p>Das passiert meist, wenn <code>cumulativeReading</code> von Hand gesenkt oder gelöscht wurde oder nach einem Restore Gesamtstand und Einstellungen nicht zusammenpassen. Bei Leistungsquellen kommt die Meldung nicht vor.</p><ol><li>Öffne die Quelle und vergleiche den „Gesamtstand“ mit deinem Zähler.</li><li>Stimmt er nicht, wähle „Zählerstand angleichen“ und trage den abgelesenen Stand ein. Das geht auch über „Angleichen“ im Tab „Probleme“ bei „Gesamtstand passt nicht zum Zähler“.</li></ol><p>Die automatische Ausrichtung zählt vom gespeicherten Gesamtstand weiter. Wurde er auf 0 gesetzt, beginnt er bei 0, bis du ihn angleichst.</p><p><strong>Siehe auch:</strong> <a href="./../anleitungen/zaehlerstaende-korrigieren#correct-wrong-too-high-negative">Falsche Werte korrigieren</a> · <a href="./falsche-werte-und-bekannte-fehler#after-update-restore-values-0">Nach Restore sind Werte 0</a></p><p><a id="error-no-cost-type-defined"></a></p><h2 id="fehler-no-cost-type-defined-–-preisdefinition-fehlt" tabindex="-1">Fehler &quot;No cost type defined&quot; – Preisdefinition fehlt <a class="header-anchor" href="#fehler-no-cost-type-defined-–-preisdefinition-fehlt" aria-label="Permalink to &quot;Fehler &quot;No cost type defined&quot; – Preisdefinition fehlt&quot;">​</a></h2><p>Der Quelle fehlt eine Preisdefinition. Die braucht jede Quelle, auch wenn du nur den Verbrauch willst, denn sie legt die Einheit fest. Klicke im Tab „Probleme“ auf „Preis wählen“ und wähle unter „Preisdefinition“ eine aus.</p><p>Der Tab „Probleme“ unterscheidet zwei Fälle:</p><ul><li>„Keine Preisdefinition gewählt“, im Log <code>No cost type defined for &lt;Datenpunkt&gt; …</code>. Das ist auch so, wenn du die Quelle am Datenpunkt im Reiter „Objekte“ eingeschaltet hast.</li><li>„Preisdefinition gibt es nicht mehr“, im Log <code>Selected Type &lt;Name&gt; does not exist in Price Definitions</code>, etwa nach dem Umbenennen einer Kategorie.</li></ul><p>Gibt es noch keinen passenden Preis, lege ihn im Tab „Preisdefinitionen“ an und speichere. Die Quelle startet nach „⚡ Übernehmen“ sofort.</p><p><strong>Siehe auch:</strong> <a href="./../referenz/einstellungen#price-definition-structured-categories-base">Preisdefinition</a> · <a href="./falsche-werte-und-bekannte-fehler#costs-stay-0-not-calculated">Kosten bleiben 0</a></p><p><a id="messages-initialization-failed-cannot-handle"></a></p><h2 id="meldungen-initialization-failed-cannot-handle-calculations-reading-incorrect" tabindex="-1">Meldungen &quot;Initialization failed&quot; / &quot;Cannot handle calculations&quot; / &quot;reading incorrect&quot; <a class="header-anchor" href="#meldungen-initialization-failed-cannot-handle-calculations-reading-incorrect" aria-label="Permalink to &quot;Meldungen &quot;Initialization failed&quot; / &quot;Cannot handle calculations&quot; / &quot;reading incorrect&quot;&quot;">​</a></h2><p>Das sind Sammelmeldungen: Eine Quelle wurde nicht gestartet. Die Ursache steht in den Log-Zeilen davor und im Tab „Probleme“, dort mit Vorschlag zur Lösung.</p><p>Häufige Ursachen davor:</p><ul><li><code>No unit defined …</code>: siehe <a href="#error-unit-not-supported-no">Einheit fehlt</a>.</li><li><code>No cost type defined …</code> oder <code>Selected Type … does not exist …</code>: siehe <a href="#error-no-cost-type-defined">Preisdefinition fehlt</a>.</li><li><code>Unit … cannot be converted …</code> oder <code>The data of … is stored in …</code>: Einheit und Preisdefinition passen nicht, siehe <a href="./../anleitungen/quellen-und-einheiten#unit-datapoint-kwh-wh-m3">Einheit nachträglich ändern</a>.</li><li><code>Cannot use output ID …</code>: Technische ID ungültig oder belegt, siehe <a href="./../referenz/einstellungen#name-datapoint-alias-output-id">Name und Output-ID</a>.</li></ul><p>Behebst du die Ursache und übernimmst, startet die Quelle ohne Neustart.</p><p>Die Meldung <code>reading incorrect after conversion contact DEV</code> sollte nicht vorkommen, weil Text und unpassende Einheiten vorher abgefangen werden. Erscheint sie doch, melde sie mit der ganzen Log-Zeile als Issue.</p><p><strong>Siehe auch:</strong> <a href="#datapoint-enabled-but-no-folders">Keine Ordner oder States</a></p><p><a id="source-delivers-text-instead-number"></a></p><h2 id="quelle-liefert-text-statt-zahl-string-statt-number-dezimalpunkt" tabindex="-1">Quelle liefert Text statt Zahl (string statt number, Dezimalpunkt) <a class="header-anchor" href="#quelle-liefert-text-statt-zahl-string-statt-number-dezimalpunkt" aria-label="Permalink to &quot;Quelle liefert Text statt Zahl (string statt number, Dezimalpunkt)&quot;">​</a></h2><p>Zahlen in Text liest SourceAnalytix selbst, mit Komma oder Punkt, etwa <code>&quot;12,5&quot;</code>. Text mit Einheit oder Tausenderpunkt wie <code>&quot;12,5 kWh&quot;</code> überspringt es. Am sichersten ist ein Datenpunkt vom Typ Zahl.</p><p>Der Tab „Probleme“ zeigt dann „Datenpunkt liefert Text statt einer Zahl“, das Log <code>Value &quot;&lt;Wert&gt;&quot; of &lt;Datenpunkt&gt; is not a number, reading ignored</code>.</p><ol><li>Prüfe, ob der Quell-Adapter den Wert auch als Zahl anbietet.</li><li>Sonst lege einen Alias vom Typ Zahl oder ein Skript mit <code>parseFloat</code> an, das den Text umwandelt, mit der Einheit des Geräts.</li><li>Richte den neuen Datenpunkt mit „Quelle hinzufügen“ ein und übernimm den Zählerstand mit „Zählerstand angleichen“.</li></ol><p><strong>Siehe auch:</strong> <a href="./../anleitungen/quellen-und-einheiten#use-script-datapoints-unreliable-sources">Skript-Datenpunkte</a></p><p><a id="datapoint-enabled-but-no-folders"></a></p><h2 id="datenpunkt-aktiviert-aber-es-entstehen-keine-ordner-oder-states" tabindex="-1">Datenpunkt aktiviert, aber es entstehen keine Ordner oder States <a class="header-anchor" href="#datenpunkt-aktiviert-aber-es-entstehen-keine-ordner-oder-states" aria-label="Permalink to &quot;Datenpunkt aktiviert, aber es entstehen keine Ordner oder States&quot;">​</a></h2><p>Fast immer hat SourceAnalytix die Quelle abgelehnt, meist wegen fehlender Preisdefinition oder Einheit. Im Tab „Übersicht“ hat sie dann den Status „Problem“, im Tab „Probleme“ stehen Grund und Lösung.</p><ol><li><strong>Läuft die Instanz?</strong> Sonst rechnet SourceAnalytix nicht.</li><li><strong>Steht die Quelle in der „Übersicht“?</strong> Wenn nicht, ist sie für eine andere Instanz eingerichtet. Lege sie mit „Quelle hinzufügen“ an.</li><li><strong>Status „Deaktiviert“?</strong> Wähle bei der Quelle „Aktivieren“.</li><li><strong>Status „Problem“?</strong> Der Knopf im Tab „Probleme“ behebt es oder führt zur passenden Stelle.</li><li><strong>Ist „Verbrauch“ an?</strong> Ohne den Haken entstehen keine Verbrauchswerte.</li></ol><p>Läuft die Quelle, entsteht der Ordner <code>sourceanalytix.0.&lt;Gerät&gt;</code> sofort, die Werte mit dem nächsten Wert des Datenpunkts. Fehlt der Ordner im Reiter „Objekte“, lade die Ansicht neu und prüfe die Filter.</p><p><strong>Siehe auch:</strong> <a href="./../erste-schritte/erster-zaehler#configure-sourceanalytix-datapoint">Wo konfiguriere ich SourceAnalytix?</a></p><p><a id="high-cpu-memory-use-too"></a></p><h2 id="hohe-cpu-speicherlast-und-zu-viel-log-ausgabe" tabindex="-1">Hohe CPU-/Speicherlast und zu viel Log-Ausgabe <a class="header-anchor" href="#hohe-cpu-speicherlast-und-zu-viel-log-ausgabe" aria-label="Permalink to &quot;Hohe CPU-/Speicherlast und zu viel Log-Ausgabe&quot;">​</a></h2><p>SourceAnalytix rechnet bei jedem neuen Wert jeder Quelle. Last entsteht vor allem durch Quellen, die sehr oft senden. Für weniger Log-Ausgabe stellst du die Instanz auf die Stufe „warn“.</p><ul><li>Stelle im Quell-Adapter ein längeres Sendeintervall ein, wenn das geht.</li><li>Nimm einen Zählerstand statt der Leistung, wenn das Gerät beides liefert.</li><li>Pausiere Quellen, die du nicht brauchst, mit „Deaktivieren“.</li></ul><p>Die Log-Stufe stellst du im Reiter „Instanzen“ im Expertenmodus ein. Füllt ein anderer Adapter das Log, hilft dessen Log-Stufe.</p><p><strong>Siehe auch:</strong> <a href="#object-limit-warning-5000">Objektlimit</a></p><p><a id="installation-admin-display-problems"></a></p><h2 id="probleme-bei-installation-und-admin-anzeige" tabindex="-1">Probleme bei Installation und Admin-Anzeige <a class="header-anchor" href="#probleme-bei-installation-und-admin-anzeige" aria-label="Permalink to &quot;Probleme bei Installation und Admin-Anzeige&quot;">​</a></h2><p>Installiere aus dem Repository „latest“, nicht von GitHub, und prüfe die <a href="./../erste-schritte/installation#requirements-sourceanalytix-have-node-js">Voraussetzungen</a>. Fehlt danach etwas in Admin, lade die Dateien mit <code>iobroker upload sourceanalytix</code> neu hoch.</p><table tabindex="0"><thead><tr><th>Symptom</th><th>Lösung</th></tr></thead><tbody><tr><td>GitHub-Installation bricht mit 404 oder 422 ab</td><td>js-controller aktualisieren oder aus „latest“ installieren</td></tr><tr><td>keine Instanz unter „Instanzen“</td><td>Instanz anlegen</td></tr><tr><td><code>Cannot load jsonConfig of sourceanalytix: Not exists</code></td><td><code>iobroker upload sourceanalytix</code>, Seite neu laden</td></tr><tr><td>„Übersicht“ leer, „Instanz läuft nicht“</td><td>Instanz starten, „Erneut versuchen“</td></tr><tr><td>„nicht gepflegt“</td><td>kommt von einer GitHub-Installation, ohne Wirkung</td></tr><tr><td>Multihost: „admin not found“</td><td>Admin auf dem Host installieren oder aktualisieren</td></tr></tbody></table><p><strong>Siehe auch:</strong> <a href="./../erste-schritte/installation#install-sourceanalytix-create-instance">Installation</a> · <a href="./../anleitungen/betrieb-und-wartung#update-sourceanalytix-downgrade">Update</a></p><p><a id="midnight-crash-rollover-wrong-time"></a></p><h2 id="mitternacht-absturz-oder-tageswechsel-zur-falschen-zeit" tabindex="-1">Mitternacht: Absturz oder Tageswechsel zur falschen Zeit <a class="header-anchor" href="#mitternacht-absturz-oder-tageswechsel-zur-falschen-zeit" aria-label="Permalink to &quot;Mitternacht: Absturz oder Tageswechsel zur falschen Zeit&quot;">​</a></h2><p>Der Wechsel läuft um 0:00 Uhr nach der Systemzeit des ioBroker-Rechners. Kommt er zur falschen Stunde, stimmt dort die Zeitzone nicht. Einen Absturz mit <code>ENOENT</code> um Mitternacht verursacht der js-controller beim Wechsel der Log-Datei; den verpassten Wechsel holt SourceAnalytix danach selbst nach.</p><p>Läuft ioBroker in Docker auf UTC, wechselt der Tag in Deutschland um 1:00 oder 2:00 Uhr. Setze dann die Umgebungsvariable <code>TZ=Europe/Berlin</code> und starte den Container neu.</p><p>Fehlt ein Wechsel, zeigt der Tab „Probleme“ „Periodenwechsel verpasst“ mit „Nachholen“, siehe <a href="./../anleitungen/betrieb-und-wartung#iobroker-was-down-midnight-recover">ioBroker war um Mitternacht aus</a>.</p><p><a id="object-limit-warning-5000"></a></p><h2 id="warnung-zum-objektlimit-5000" tabindex="-1">Warnung zum Objektlimit (5000) <a class="header-anchor" href="#warnung-zum-objektlimit-5000" aria-label="Permalink to &quot;Warnung zum Objektlimit (5000)&quot;">​</a></h2><p>Die Warnung kommt vom js-controller, SourceAnalytix selbst kennt kein Limit. Jede Quelle legt viele States an. Prüfe zuerst, was du brauchst:</p><ul><li>Schalte unter „Haupteinstellungen“ Perioden-Optionen aus, die du nicht nutzt.</li><li>Lösche nicht mehr gebrauchte Quellen mit „Daten löschen“.</li><li>Lösche alte Jahresordner.</li></ul><p>Ist die Zahl gewollt, lässt sich das Limit im Expertenmodus am Objekt <code>system.adapter.sourceanalytix.0</code> anheben.</p><p><strong>Siehe auch:</strong> <a href="./../referenz/einstellungen#instance-settings-exist-periods-decimals">Instanz-Einstellungen</a></p><p><a id="source-adapter-history-shows-0"></a></p><h2 id="quell-adapter-oder-history-zeigt-0-oder-alte-werte" tabindex="-1">Quell-Adapter oder History zeigt 0 oder alte Werte <a class="header-anchor" href="#quell-adapter-oder-history-zeigt-0-oder-alte-werte" aria-label="Permalink to &quot;Quell-Adapter oder History zeigt 0 oder alte Werte&quot;">​</a></h2><p>Am Quell-Datenpunkt kommt meist nichts mehr an. SourceAnalytix liest ihn nur und schreibt nie in seinen Wert; eine 0 im Verlauf des Quell-Datenpunkts stammt vom Adapter oder einem Skript.</p><p>Hat der Quell-Adapter seine Datenpunkte umbenannt, hört SourceAnalytix weiter auf den alten:</p><ol><li>Prüfe bei der Quelle „Letzte Aktualisierung“. Ist der alte Datenpunkt gelöscht, meldet der Tab „Probleme“ „Datenpunkt existiert nicht mehr“.</li><li>Lege den neuen Datenpunkt mit „Quelle hinzufügen“ an und übernimm den Stand mit „Zählerstand angleichen“.</li><li>Passe VIS und Skripte auf den neuen Ordner an. Der alte bleibt als Archiv.</li></ol>',71)])])}const g=t(l,[["render",o]]);export{p as __pageData,g as default};
